<?php
use App\Models\{PengaturanSekolah,User}; use Illuminate\Support\Facades\Storage; use Livewire\Component; use Livewire\WithFileUploads;
new class extends Component { use WithFileUploads; public array $form=[]; public $logo;
public function mount():void{$this->form=PengaturanSekolah::firstOrCreate(['id'=>1],['nama_sekolah'=>'SD Negeri 232 Maluku Tengah'])->only(['nama_sekolah','npsn','alamat','telepon','email','kepala_sekolah_user_id']);}
public function save():void{abort_unless(auth()->user()->can('pengaturan.update'),403);$d=$this->validate(['form.nama_sekolah'=>'required|string|max:255','form.npsn'=>'nullable|string|max:30','form.alamat'=>'nullable|string|max:1000','form.telepon'=>'nullable|string|max:30','form.email'=>'nullable|email','form.kepala_sekolah_user_id'=>'nullable|exists:users,id','logo'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:2048']);$s=PengaturanSekolah::first();$payload=$d['form'];if($this->logo){if($s->logo)Storage::disk('public')->delete($s->logo);$payload['logo']=$this->logo->store('logo-sekolah','public');}$s->update($payload);session()->flash('success','Pengaturan sekolah berhasil diperbarui.');}
public function with():array{return ['setting'=>PengaturanSekolah::first(),'kepala'=>User::role('kepala_sekolah')->orderBy('name')->get()];}}; ?>
<div><div class="mb-6"><p class="text-sm font-semibold text-sky-700">Manajemen</p><h1 class="page-title">Pengaturan Sekolah</h1><p class="page-subtitle">Informasi ini digunakan pada header laporan, print, dan PDF.</p></div><form wire:submit="save" class="card max-w-4xl"><div class="grid gap-5 p-5 sm:grid-cols-2"><div class="sm:col-span-2"><label class="form-label">Nama Sekolah <span>*</span></label><input wire:model="form.nama_sekolah" class="form-input">@error('form.nama_sekolah')<p class="form-error">{{$message}}</p>@enderror</div><div><label class="form-label">NPSN</label><input wire:model="form.npsn" class="form-input"></div><div><label class="form-label">Telepon</label><input wire:model="form.telepon" class="form-input"></div><div><label class="form-label">Email</label><input type="email" wire:model="form.email" class="form-input"></div><div><label class="form-label">Kepala Sekolah</label><select wire:model="form.kepala_sekolah_user_id" class="form-input"><option value="">Belum ditentukan</option>@foreach($kepala as $k)<option value="{{$k->id}}">{{$k->name}}</option>@endforeach</select></div><div class="sm:col-span-2"><label class="form-label">Alamat</label><textarea wire:model="form.alamat" class="form-input min-h-24"></textarea></div><div class="sm:col-span-2"><label class="form-label">Logo (PNG/JPG/WebP, maks. 2 MB)</label><input type="file" wire:model="logo" accept="image/png,image/jpeg,image/webp" class="form-input p-2">@error('logo')<p class="form-error">{{$message}}</p>@enderror @if($setting?->logo)<img src="{{Storage::url($setting->logo)}}" alt="Logo sekolah saat ini" class="mt-3 size-20 rounded-xl border object-contain p-2">@endif</div></div><div class="flex justify-end border-t p-5"><button class="btn-primary" wire:loading.attr="disabled">Simpan Pengaturan</button></div></form></div>
